"""Reused workspace portfolio, extracted from the _BONUS_SRC literal in
adaptive_dicke_validation/snapshots/kai-48115b9/submission.py (Astra bonus).
This is prior work, not a new interference or Yu-paper result. Local changes
extend the public domain to N=20 and guard adaptive layouts by supported size.

Analytic recurrences are supplemented by independently synthesized, embedded
native seeds. No fitting, calibration maps, external files, or hardware
submission imports are needed at runtime. The public function returns a fresh
circuit and output set. See verify_bonus.py for full-state and all-branch checks.
"""
from __future__ import annotations

import functools
import collections
import math
import random

import cirq
import cirq_google
import numpy as np
import sympy


H = cirq.unitary(cirq.H)
X = cirq.unitary(cirq.X)
I = np.eye(2, dtype=np.complex128)


def ry(theta):
    c, s = math.cos(theta / 2), math.sin(theta / 2)
    return np.array([[c, -s], [s, c]], dtype=np.complex128)


def _u(ops, q, matrix):
    ops.append((q, matrix))


def _cx(ops, a, b):
    ops.extend([(b, H), (a, b), (b, H)])


def _identity(matrix):
    return np.linalg.norm(matrix - np.trace(matrix) * I / 2) < 2e-14


def _compile(ops):
    """Fuse local matrices between CZs and ASAP-pack mixed native moments.

    A CZ flushes only its two operands, so disjoint rotations and entanglers
    share moments.  Local identity up to phase can be dropped because these
    are unconditional operations.  Never apply that rule to feedforward gates.
    """
    pending = {}
    emitted = []

    def flush(q):
        matrix = pending.pop(q, None)
        if matrix is not None and not _identity(matrix):
            emitted.append(cirq.PhasedXZGate.from_matrix(matrix).on(q))

    for a, b in ops:
        if isinstance(b, np.ndarray):
            pending[a] = b @ pending.get(a, I)
        else:
            flush(a)
            flush(b)
            emitted.append(cirq.CZ(a, b))
    for q in list(pending):
        flush(q)
    return cirq.Circuit(emitted, strategy=cirq.InsertStrategy.EARLIEST)


def _optimize_frames(circuit):
    """Commute exact Pauli/Z frames through CZs, then refold local layers."""
    best = circuit
    for _ in range(3):
        c = cirq.eject_z(best, atol=1e-13)
        c = cirq.eject_phased_paulis(c, atol=1e-13)
        c = cirq.merge_single_qubit_gates_to_phxz(c, atol=1e-13)
        c = cirq.drop_negligible_operations(c, atol=1e-13)
        ops = []
        for op in c.all_operations():
            if not op.qubits:
                continue
            if len(op.qubits) == 1:
                ops.append((op.qubits[0], cirq.unitary(op)))
            else:
                assert op.gate == cirq.CZ
                ops.append(op.qubits)
        c = _compile(ops)
        if len(c) >= len(best):
            break
        best = c
    return best


def _schedule_commuting(circuit, trials=6):
    """Resource-constrained scheduling of an exact commutation DAG.

    Diagonal gates commute even when they share a wire. Every other shared
    wire ordering is retained, so this never approximates the unitary.
    """
    ops = list(circuit.all_operations())
    successors = [set() for _ in ops]
    predecessors = [set() for _ in ops]
    diagonal = []
    for op in ops:
        matrix = cirq.unitary(op) if len(op.qubits) == 1 else None
        diagonal.append(matrix is None or abs(matrix[0,1])+abs(matrix[1,0]) < 1e-13)
    by_qubit = {}
    for j,op in enumerate(ops):
        for q in op.qubits:
            for i in by_qubit.get(q,[]):
                if not (diagonal[i] and diagonal[j]):
                    predecessors[j].add(i)
                    successors[i].add(j)
            by_qubit.setdefault(q,[]).append(j)
    heights = [0]*len(ops)
    for i in range(len(ops)-1,-1,-1):
        heights[i] = 1+max((heights[j] for j in successors[i]),default=0)
    best = circuit
    for seed in range(trials):
        rng = random.Random(seed)
        ranks = [rng.random() for _ in ops]
        counts = [len(p) for p in predecessors]
        ready = {i for i,n in enumerate(counts) if n == 0}
        moments = []
        while ready:
            busy,chosen = set(),[]
            for i in sorted(ready,key=lambda i:(-heights[i],ranks[i])):
                if not busy.intersection(ops[i].qubits):
                    chosen.append(i)
                    busy.update(ops[i].qubits)
            moments.append(cirq.Moment(ops[i] for i in chosen))
            ready.difference_update(chosen)
            for i in chosen:
                for j in successors[i]:
                    counts[j] -= 1
                    if counts[j] == 0:
                        ready.add(j)
        candidate = cirq.Circuit(moments)
        assert sum(len(m) for m in candidate) == len(ops)
        if len(candidate) < len(best):
            best = candidate
    return best


def _optimize_depth(circuit):
    best = _optimize_frames(circuit)
    current = circuit
    # Equal-depth frame changes can unlock a later saving; do not stop early.
    for _ in range(4):
        current = cirq.eject_z(current,atol=1e-13)
        current = cirq.eject_phased_paulis(current,atol=1e-13)
        current = cirq.merge_single_qubit_gates_to_phxz(current,atol=1e-13)
        current = cirq.drop_negligible_operations(current,atol=1e-13)
        current = _schedule_commuting(current)
        if len(current) < len(best):
            best = current
    return best


@functools.lru_cache(maxsize=1)
def _graph():
    metadata = cirq_google.Willow105.metadata
    graph = {q: set() for q in metadata.qubit_set}
    for a, b in metadata.qubit_pairs:
        graph[a].add(b)
        graph[b].add(a)
    return graph


def _givens(ops, a, b, theta):
    """Full real excitation-preserving rotation: 10 -> cos*10 + sin*01.

    Conjugating opposite Ry rotations by H.H CZ gives this exact two-CZ
    formula, retaining the common phase on the vacuum and occupied branches.
    """
    ops.extend([(a,H),(b,H),(a,b),(a,ry(theta)),(b,ry(-theta)),
                (a,b),(a,H),(b,H)])


@functools.lru_cache(maxsize=256)
def _givens_native(theta):
    c, s = math.cos(theta), math.sin(theta)
    matrix = np.array([[1, 0, 0, 0], [0, c, s, 0],
                       [0, -s, c, 0], [0, 0, 0, 1]], dtype=complex)
    a, b = cirq.LineQubit.range(2)
    # A single omitted global phase is common to every input weight. It is
    # therefore harmless for this unconditional subroutine. A local scalar is
    # harmless for the whole unitary, unlike a weight-dependent phase.
    return tuple(cirq.two_qubit_matrix_to_cz_operations(
        a, b, matrix, allow_partial_czs=False, atol=1e-12))


def _reflect3(ops, a, b, c, m, ell):
    """Core five-CZ restricted isometry on path a-b-c.

    Reverse of the core module's c-a-b convention. Allowed inputs:
    000->000, 100->sqrt(ell/m)100+sqrt(1-ell/m)010,
    101->011, 110->110, 111->111. All phases are identical.
    """
    theta = math.acos(math.sqrt(ell / m))
    bp, ap = (theta + math.pi / 2) / 2, (theta - math.pi / 2) / 2
    _cx(ops, b, a)
    ops.extend([(b, ry(-bp)), (c, b), (b, ry(-ap)), (a, b),
                (b, ry(ap)), (c, b), (b, ry(bp))])
    _cx(ops, b, a)


def _unary3(ops, q):
    """Analytic six-CZ isometry, valid ONLY for input weights 0,1,2.

    Adapted read-only from astra/research/exact_u3.py; its domain restriction
    matters: this is not a U(3,3). The general routine handles weight three.
    """
    a = math.asin(1 / math.sqrt(3))
    angles = [-math.pi/2, math.pi, a-math.pi, -math.pi/2, a-math.pi,
              math.pi/2+a, a, -math.pi/2, -math.pi/2, -math.pi/2, 0,
              -math.pi/4, math.pi/4, math.pi/2, math.pi/2]
    edges = [(1, 2), (0, 1), (1, 2), (0, 1), (1, 2), (1, 2)]
    for i in range(3):
        _u(ops, q[i], ry(angles[i]))
    for j, (u, v) in enumerate(edges):
        ops.append((q[u], q[v]))
        _u(ops, q[u], ry(angles[3+2*j]))
        _u(ops, q[v], ry(angles[4+2*j]))


def _unary_legacy(ops, q, k, small=True):
    """Coherently decode 1^j 0^(m-j) for every 0<=j<=k.

    Baertschi--Eidenbenz SCS with wire movement absorbed in the reverse
    staircase. No restoration swaps; disjoint blocks pipeline automatically.
    """
    if len(q) == 3 and k == 2 and small:
        _unary3(ops, q)
        return
    for start in range(len(q)-1):
        m = len(q)-start
        if m == 3 and k == 2 and small:
            _unary3(ops, q[start:])
            break
        width = min(k, m-1)
        if width == 0:
            break
        a, b = q[start+width-1], q[start+width]
        theta = math.acos(math.sqrt(width/m))
        if m > k+1:
            # This is the first operation reaching b: it is still zero.
            eta = math.pi/2-theta
            _u(ops,b,ry(eta))
            _cx(ops,a,b)
            _u(ops,b,ry(-eta))
            _cx(ops,b,a)
        else:
            _givens(ops, a, b, theta)
        for ell in range(width-1, 0, -1):
            _reflect3(ops, *q[start+ell-1:start+ell+2], m, ell)


def _unary3_full_forward(ops, q):
    """Eight-CZ coherent U(3,3), independently synthesized and analyticized.

    All four unary columns, including 111, have the same phase.
    """
    a = math.asin(1/math.sqrt(3))
    h = math.pi/2
    angles = [h,h,h,h+a,math.pi-a,h,h+a/2,-h+a/2,h,0,
              h+a/2,-h+a/2,-h,3*h,-3*math.pi/4,h,-5*math.pi/4,h,-h]
    for i in range(3):
        _u(ops,q[i],ry(angles[i]))
    for j in range(8):
        u,v = q[j%2],q[1+j%2]
        ops.append((u,v))
        _u(ops,u,ry(angles[3+2*j]))
        _u(ops,v,ry(angles[4+2*j]))


def _unary3_full(ops,q):
    # Spin complement plus wire reversal preserves every unary-to-Dicke column.
    # This orientation lets the suffix start earlier at a decoder boundary.
    ops.extend((x,X) for x in q)
    _unary3_full_forward(ops,q[::-1])
    ops.extend((x,X) for x in q)


def _scs_pair(ops, q, m, ell):
    """Four-CZ fused SCS window, input columns 000,100,110.

    100 -> sqrt(ell/m)100 + sqrt(1-ell/m)010;
    110 -> sqrt((ell+1)/m)110 + sqrt(1-(ell+1)/m)011.
    Independently derived by real-isometry synthesis then analyticized.
    """
    a,b = math.asin(math.sqrt(ell/m)),math.asin(math.sqrt((ell+1)/m))
    h = math.pi/2
    angles = [-h,math.pi,h+b,-h,h+b,h+a,a-math.pi,h,0,-h,h]
    for i in range(3):
        _u(ops,q[i],ry(angles[i]))
    for j,(u,v) in enumerate([(1,2),(0,1),(1,2),(0,1)]):
        ops.append((q[u],q[v]))
        _u(ops,q[u],ry(angles[3+2*j]))
        _u(ops,q[v],ry(angles[4+2*j]))


def _unary(ops, q, k, small=True):
    if small == 'fused':
        return _unary_fused(ops,q,k)
    if small == 'pruned':
        return _unary_pruned(ops,q,k)
    return _unary_legacy(ops,q,k,small)


def _unary_fused(ops,q,k):
    for start in range(len(q)-1):
        m = len(q)-start
        if m == 3 and k >= 3:
            _unary3_full(ops,q[start:])
            break
        width = min(k,m-1)
        if m > k and width >= 2:
            _scs_pair(ops,q[start+width-2:start+width+1],m,width-1)
            for ell in range(width-2,0,-1):
                _reflect3(ops,*q[start+ell-1:start+ell+2],m,ell)
        else:
            a,b = q[start+width-1],q[start+width]
            _givens(ops,a,b,math.acos(math.sqrt(width/m)))
            for ell in range(width-1,0,-1):
                _reflect3(ops,*q[start+ell-1:start+ell+2],m,ell)


def _reflect4(ops, a, b, c, theta, skip=False):
    """Claude's four-CZ isometry in our reversed wire convention."""
    if not skip:
        _cx(ops, b, a)
    ops.extend([(b, ry(-theta)), (a, b), (b, ry(-math.pi/2)),
                (c, b), (b, ry(theta+math.pi/2))])
    _cx(ops, b, a)


@functools.lru_cache(maxsize=64)
def _classical_map(source, target):
    """Shortest adjacent-CX/X realization on a promised three-bit support."""
    queue = collections.deque([(source, ())])
    seen = {source}
    gates = [(a,b) for a,b in [(0,1),(1,0),(1,2),(2,1)]]
    gates += [(a,a) for a in range(3)]
    while queue:
        state, path = queue.popleft()
        if state == target:
            return path
        for a,b in gates:
            nxt = tuple(s ^ ((1 << (2-b)) if a == b or s & (1 << (2-a)) else 0)
                        for s in state)
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, path+((a,b),)))
    raise ValueError('No affine support realization')


def _unary_pruned(ops, q, k, jmin=0, jmax=None):
    """Track exact combinatorial support, with no amplitudes or state fitting."""
    jmax = min(k,len(q)) if jmax is None else jmax
    support = {tuple([1]*j+[0]*(len(q)-j)) for j in range(jmin,jmax+1)}

    def apply(indices, mapping):
        nonlocal support
        changed = set()
        for state in support:
            local = tuple(state[i] for i in indices)
            for output in mapping.get(local, [local]):
                result = list(state)
                for i,v in zip(indices,output):
                    result[i] = v
                changed.add(tuple(result))
        support = changed

    for start in range(len(q)-1):
        m = len(q)-start
        if m == 3:
            if k == 2:
                _unary3(ops,q[start:])
                break
            if k >= 3:
                _unary3_full(ops,q[start:])
                break
        width = min(k,m-1)
        indices = [start+width-1,start+width]
        a,b = [q[i] for i in indices]
        s = {tuple(state[i] for i in indices) for state in support}
        theta = math.acos(math.sqrt(width/m))
        if (1,0) in s:
            if s == {(1,0)}:
                _u(ops,b,ry(2*theta))
                _cx(ops,b,a)
            elif (1,1) not in s:
                eta = math.pi/2-theta
                _u(ops,b,ry(eta))
                _cx(ops,a,b)
                _u(ops,b,ry(-eta))
                _cx(ops,b,a)
            else:
                _givens(ops,a,b,theta)
        apply(indices,{(1,0):[(1,0),(0,1)]})
        for ell in range(width-1,0,-1):
            indices = list(range(start+ell-1,start+ell+2))
            a,b,c = [q[i] for i in indices]
            s = {tuple(state[i] for i in indices) for state in support}
            theta = math.acos(math.sqrt(ell/m))
            p,r = (1,0,0) in s,(1,0,1) in s
            if p and r:
                if (1,1,1) not in s:
                    _reflect4(ops,a,b,c,theta,skip=(1,1,0) not in s)
                else:
                    _reflect3(ops,a,b,c,m,ell)
            elif p:
                _givens(ops,a,b,theta)
            elif r:
                source = tuple(sorted(4*x+2*y+z for x,y,z in s))
                target = tuple(3 if v == 5 else v for v in source)
                for u,v in _classical_map(source,target):
                    if u == v:
                        _u(ops,[a,b,c][u],X)
                    else:
                        _cx(ops,[a,b,c][u],[a,b,c][v])
            apply(indices,{(1,0,0):[(1,0,0),(0,1,0)],(1,0,1):[(0,1,1)]})


def _ladder(a, b, k):
    """Find k rungs with two nonintersecting path extensions on Willow."""
    graph = _graph()

    def paths(prefix, length, occupied):
        if len(prefix) == length:
            yield prefix
        else:
            for nxt in sorted(graph[prefix[-1]] - occupied):
                yield from paths(prefix+[nxt], length, occupied | {nxt})

    roots = sorted(graph, key=lambda q: ((q.row-6)**2+(q.col-7)**2, q))
    for root in roots:
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            for sr, sc in [(-dc, dr), (dc, -dr)]:
                top = [cirq.GridQubit(root.row+i*dr, root.col+i*dc) for i in range(k)]
                bottom = [cirq.GridQubit(root.row+(k-1-i)*dr+sr,
                                         root.col+(k-1-i)*dc+sc) for i in range(k)]
                core = set(top+bottom)
                if len(core) != 2*k or not core <= graph.keys():
                    continue
                edges = list(zip(top, top[1:])) + list(zip(bottom, bottom[1:]))
                edges += [(top[j], bottom[k-1-j]) for j in range(k)]
                if any(y not in graph[x] for x, y in edges):
                    continue
                for full_top in paths(top, a, core):
                    full_bottom = next(paths(bottom, b, core | set(full_top)), None)
                    if full_bottom is not None:
                        return full_top, full_bottom
    raise RuntimeError('No Willow ladder found')


def _divide(n, k, a=None, small=True, pivot=0, left_first=False):
    a = n//2 if a is None else a
    b = n-a
    top, bottom = _ladder(a, b, k)
    weights = [math.comb(a, j)*math.comb(b, k-j) for j in range(k+1)]
    tail = [sum(weights[j:]) for j in range(k+1)]
    ops = [(q, X) for q in bottom[:k]]
    prefix = [sum(weights[:j+1]) for j in range(k+1)]
    _u(ops,top[pivot],ry(2*math.asin(math.sqrt(tail[pivot+1]/tail[0]))))
    def expand_right():
        for j in range(pivot+1,k):
            eta = math.pi/2-math.asin(math.sqrt(tail[j+1]/tail[j]))
            _u(ops,top[j],ry(eta))
            _cx(ops,top[j-1],top[j])
            _u(ops,top[j],ry(-eta))
    def expand_left():
        for j in range(pivot-1,-1,-1):
            eta = math.pi/2-math.asin(math.sqrt(prefix[j]/prefix[j+1]))
            _u(ops,top[j+1],X)
            _u(ops,top[j],ry(eta))
            _cx(ops,top[j+1],top[j])
            _u(ops,top[j],ry(-eta))
            _u(ops,top[j+1],X)
            _u(ops,top[j],X)
    if left_first:
        expand_left();expand_right()
    else:
        expand_right();expand_left()
    for j in range(k):
        _cx(ops, top[j], bottom[k-1-j])
    _unary(ops, top, k, small)
    _unary(ops, bottom, k, small)
    return _compile(ops), set(top+bottom)


def _square():
    q = [cirq.GridQubit(4,4), cirq.GridQubit(4,5),
         cirq.GridQubit(5,5), cirq.GridQubit(5,4)]
    a = math.acos(1/math.sqrt(3))
    ops = []
    layers = [[ry(a-math.pi/2), H, ry(-a), H],
              [ry(math.pi/2), ry(-math.pi/2)@H, ry(3*math.pi/2), ry(-math.pi-a)@H],
              [I, ry(-math.pi), ry(-math.pi/2), ry(-math.pi/2)],
              [ry(a-math.pi), ry(2*a), ry(a), ry(a-math.pi/2)]]
    for i, layer in enumerate(layers):
        ops.extend(zip(q, layer))
        if i < 3:
            ops.extend([(q[0],q[1]),(q[2],q[3])] if i%2 == 0
                       else [(q[1],q[2]),(q[3],q[0])])
    return _compile(ops), set(q)


