_BINARY_DECODER3 = {'angles': [2.082506231059624e-16,
            1.5707963267948966,
            1.5707963267948966,
            -1.5707963267948963,
            -0.9553166181245092,
            -3.141592653589793,
            2.5261129449194057,
            2.356194490192345,
            1.5707963267948966,
            1.5707963267948966,
            -1.5707963267948968,
            0.7853981633974482,
            3.1415926535897936,
            1.5707963267948966,
            -1.5707963267948966,
            1.5707963267948968,
            -7.873629922416639e-17],
 'edges': [[1, 2], [0, 1], [1, 2], [0, 1], [1, 2], [0, 1], [1, 2]]}

def _binary_decoder3(ops, q):
    """Coherently map binary (low, high, 0) to D(3,j), j=0..3."""
    data = _BINARY_DECODER3
    for i in range(3):
        _u(ops,q[i],ry(data['angles'][i]))
    for j,(a,b) in enumerate(data['edges']):
        ops.append((q[a],q[b]))
        _u(ops,q[a],ry(data['angles'][3+2*j]))
        _u(ops,q[b],ry(data['angles'][4+2*j]))


def _binary_three_arm(n,k,open_center=False):
    data = _BINARY_ARM_SEEDS.get((n,k))
    if data is None:
        return None
    arms = [[cirq.GridQubit(4+i,4+j) for j in range(size)]
            for i,size in enumerate(data['sizes'])]
    roots = [q for arm in arms for q in arm[:2]]
    outputs = {q for arm in arms for q in arm}
    ops = []
    for layer in range(len(data['layers'])+1):
        if layer:
            ops.extend((roots[a],roots[b]) for a,b in data['layers'][layer-1])
        for i,q in enumerate(roots):
            _u(ops,q,ry(data['angles'][6*layer+i]))
    for arm in arms:
        if len(arm) == 3:
            _binary_decoder3(ops,arm)
        else:
            assert len(arm) == 2
            _cx(ops,arm[1],arm[0])
            _givens(ops,*arm,math.pi/4)
    if open_center:
        # Free the enclosed central output for the exterior-cat layout. Each
        # two-CNOT move has a known-zero destination and restores its source.
        assert n == 9
        center,neighbor,bridge,fresh = [cirq.GridQubit(5,c) for c in [5,6,7,8]]
        for source,dest in [(neighbor,bridge),(bridge,fresh),(center,neighbor)]:
            _cx(ops,source,dest); _cx(ops,dest,source)
        outputs.remove(center); outputs.add(fresh)
    return _optimize_depth(_compile(ops)),outputs


def _three_arm(n):
    data = _THREE_ARM_SEEDS.get(n)
    if data is None:
        return None
    arms = [[cirq.GridQubit(4+i,4+j) for j in range(size)]
            for i,size in enumerate(data['sizes'])]
    roots = [q for arm in arms for q in arm[:2]]
    ops = []
    for layer in range(len(data['layers'])+1):
        if layer:
            ops.extend((roots[a],roots[b]) for a,b in data['layers'][layer-1])
        for i,q in enumerate(roots):
            _u(ops,q,ry(data['angles'][6*layer+i]))
    for arm in arms:
        _unary_fused(ops,arm,2)
    return _optimize_depth(_compile(ops)),{q for arm in arms for q in arm}


def _native_seed(n,k):
    data = _NATIVE_SEEDS.get((n,k))
    if data is None:
        return None
    q = [cirq.GridQubit(4+r,4+c) for r,c in data['coords']]
    ops = []
    for layer in range(len(data['layers'])+1):
        if layer:
            ops.extend((q[a],q[b]) for a,b in data['layers'][layer-1])
        for i in range(n):
            _u(ops,q[i],ry(data['angles'][layer*n+i]))
    return _optimize_depth(_compile(ops)),set(q)


def _subtract_balanced_seed(n,k):
    """Measure an isolated output diagonal, then complement the zero branch.

    A final monomial gate on the measured bit is absorbed into the readout's
    invert mask. Its phase is branch-global. Full diagonal measurements and
    remaining data gates are then scheduled together with causal feedforward.
    """
    if n != 2*k+1:
        return None
    seeds = [v for v in (_native_seed(n+1,k+1), _round4_unitary(n+1,k+1)) if v is not None]
    if not seeds:
        return None
    circuit,outputs = min(seeds,key=lambda item:len(item[0]))
    physical = _graph()
    choices = [q for q in outputs
               if sum(x.row+x.col == q.row+q.col for x in outputs) == 1]
    if not choices:
        return None
    candidates = []
    for q in sorted(choices):
        candidate = cirq.Circuit(circuit)
        index = max(i for i,m in enumerate(candidate) if q in m.qubits)
        op = candidate[index].operation_at(q)
        invert = False
        if len(op.qubits) == 1:
            matrix = cirq.unitary(op)
            diagonal_gate = abs(matrix[0,1])+abs(matrix[1,0]) < 1e-13
            antidiagonal_gate = abs(matrix[0,0])+abs(matrix[1,1]) < 1e-13
            if diagonal_gate or antidiagonal_gate:
                candidate[index] = candidate[index].without_operations_touching([q])
                invert = antidiagonal_gate
        diagonal = sorted(x for x in physical if x.row+x.col == q.row+q.col)
        candidate.append(cirq.Moment(cirq.measure(x,key=f'subtract_{x.row}_{x.col}',
                        invert_mask=(bool(invert and x == q),)) for x in diagonal))
        retained = outputs-{q}
        condition = cirq.SympyCondition(sympy.Eq(sympy.Symbol(f'subtract_{q.row}_{q.col}'),0))
        candidate.append(cirq.Moment(cirq.X(x).with_classical_controls(condition) for x in retained))
        candidate = _schedule_adaptive(candidate)
        candidates.append((candidate,retained))
    return min(candidates,key=lambda item:len(item[0]))


def _w_from_tree(rounds):
    edges = [edge for rnd in rounds for edge in rnd]
    root = edges[0][0]
    children = {}
    for a, b in edges:
        children.setdefault(a, []).append(b)
    sizes = {}

    def size(q):
        sizes[q] = 1+sum(size(c) for c in children.get(q, []))
        return sizes[q]

    size(root)
    remaining = dict(sizes)
    ops = []
    for i, (a, b) in enumerate(edges):
        theta = math.asin(math.sqrt(sizes[b]/remaining[a]))
        if i == 0:
            _u(ops, a, ry(2*theta))
            _cx(ops, a, b)
            _u(ops, a, X)
        else:
            eta = math.pi/2-theta
            _u(ops, b, ry(eta))
            _cx(ops, a, b)
            _u(ops, b, ry(-eta))
            _cx(ops, b, a)
        remaining[a] -= sizes[b]
    return _compile(ops), set(sizes)


def _w(n):
    graph = _graph()
    rng = random.Random(83419+n)
    best = None
    finalists = []
    # Fast deterministic offline-style tree search, bounded independently of
    # statevector size. Both geometry and asynchronous native depths matter.
    root = cirq.GridQubit(6,7)
    for trial in range(96):
        used = {root}
        rounds = []
        while len(used) < n:
            candidates = [(a,b) for a in sorted(used) for b in sorted(graph[a]-used)]
            rng.shuffle(candidates)
            busy, rnd = set(), []
            for a, b in candidates:
                if a in busy or b in busy:
                    continue
                rnd.append((a,b))
                busy.update((a,b))
                if len(used)+len(rnd) == n:
                    break
            rounds.append(rnd)
            used.update(b for _,b in rnd)
        candidate = _w_from_tree(rounds)
        candidate = (_optimize_frames(candidate[0]), candidate[1])
        finalists.append(candidate)
        if best is None or len(candidate[0]) < len(best[0]):
            best = candidate
    for candidate,outputs in sorted(finalists,key=lambda item:len(item[0]))[:16]:
        candidate = _optimize_depth(candidate)
        if len(candidate) < len(best[0]):
            best = candidate,outputs
    return best


def _schedule_adaptive(circuit, trials=16):
    """ASAP/list schedule with causal keys and indivisible readout diagonals.

    Shared-wire commutation is used only for unconditional diagonal unitaries.
    Every physical readout diagonal remains one scheduling block. Measurements,
    native CZs, local gates and conditional corrections can share a moment.
    """
    blocks = []
    for moment in circuit:
        measured = collections.defaultdict(list)
        for op in moment:
            if cirq.is_measurement(op):
                assert len(op.qubits) == 1
                measured[sum((op.qubits[0].row, op.qubits[0].col))].append(op)
            else:
                blocks.append((op,))
        blocks.extend(tuple(ops) for _, ops in sorted(measured.items()))
    support = [set(q for op in block for q in op.qubits) for block in blocks]
    diagonal = []
    for block in blocks:
        op = block[0]
        matrix = cirq.unitary(op, default=None) if len(block) == 1 else None
        diagonal.append(matrix is not None and not op.classical_controls and
                        (op.gate == cirq.CZ or
                         (len(op.qubits) == 1 and abs(matrix[0,1])+abs(matrix[1,0]) < 1e-13)))
    pred = [set() for _ in blocks]
    succ = [set() for _ in blocks]
    by_qubit, key_owner = {}, {}
    for j, block in enumerate(blocks):
        for q in support[j]:
            for i in by_qubit.get(q, []):
                if not (diagonal[i] and diagonal[j]):
                    pred[j].add(i)
            by_qubit.setdefault(q, []).append(j)
        for op in block:
            for key in cirq.control_keys(op):
                pred[j].add(key_owner[key])
        for op in block:
            if cirq.is_measurement(op):
                for key in cirq.measurement_key_objs(op):
                    key_owner[key] = j
        for i in pred[j]:
            succ[i].add(j)
    heights = [0]*len(blocks)
    for i in range(len(blocks)-1, -1, -1):
        heights[i] = 1+max((heights[j] for j in succ[i]), default=0)
    best = cirq.Circuit(circuit)
    for seed in range(trials):
        rng = random.Random(983+seed)
        ranks = [rng.random() for _ in blocks]
        counts = [len(p) for p in pred]
        ready = {i for i, count in enumerate(counts) if not count}
        moments = []
        while ready:
            busy, chosen = set(), []
            for i in sorted(ready, key=lambda i:(-heights[i], ranks[i])):
                if not busy.intersection(support[i]):
                    chosen.append(i); busy.update(support[i])
            moments.append(cirq.Moment(op for i in chosen for op in blocks[i]))
            ready.difference_update(chosen)
            for i in chosen:
                for j in succ[i]:
                    counts[j] -= 1
                    if counts[j] == 0:
                        ready.add(j)
        assert sum(len(m) for m in moments) == sum(len(b) for b in blocks)
        if len(moments) < len(best):
            best = cirq.Circuit(moments)
    return best


@functools.lru_cache(maxsize=128)
def _best(n, k):
    prebuilt = _round5_unitary(n,k) or _round4_unitary(n,k)
    if prebuilt is not None:
        c,q = prebuilt
        method = _ROUND5_VERIFIED.get((n,k), _ROUND4_VERIFIED.get((n,k)))['method']
        subtraction = _subtract_balanced_seed(n,k)
        if subtraction is not None and len(subtraction[0]) < len(c):
            c,q = subtraction
            method = 'verified balanced seed + deterministic measurement/complement'
        if n == 2*k:
            adaptive = balanced_candidate(n)
            if len(adaptive['circuit']) < len(c):
                c,q = cirq.Circuit(adaptive['circuit']),set(adaptive['outputs'])
                method = 'adaptive cat complement + even-site teleportation'
        for op in c.all_operations():
            cirq_google.Willow105.validate_operation(op.without_classical_controls())
        if not c.has_measurements():
            cirq_google.Willow105.validate_circuit(c)
        return cirq.FrozenCircuit(c),frozenset(q),method
    if k == 1:
        c, q = _w(n)
        method = 'parallel W tree'
    elif (n, k) == (4, 2):
        c, q = _square()
        method = 'analytic square'
    else:
        candidates = []
        for a in sorted({n//2, (n+1)//2}):
            for small in (['fused', True, False, 'pruned'] if k == 2 else ['fused', False, 'pruned']):
                candidate, outputs = _divide(n, k, a, small)
                candidate = _optimize_depth(candidate)
                candidates.append((len(candidate), candidate, outputs,
                                   f'hypergeometric {a}+{n-a}' +
                                   (' / '+small if isinstance(small,str) else ' / U3' if small else '')))
            if n%2 == 0 and k >= 3:
                candidate,outputs = _divide(n,k,a,small='fused',pivot=k//2)
                candidate = _optimize_depth(candidate)
                candidates.append((len(candidate),candidate,outputs,
                                   f'hypergeometric {a}+{n-a} / center-out seed'))
        _, c, q, method = min(candidates, key=lambda item:item[0])
        seed = _native_seed(n,k)
        if seed is not None and len(seed[0]) < len(c):
            c,q = seed
            method = 'independent native grid seed'
        arms = _three_arm(n) if k == 2 else None
        if arms is not None and len(arms[0]) < len(c):
            c,q = arms
            method = 'three-arm unary distribution + parallel decoders'
        binary = _binary_three_arm(n,k)
        if binary is not None and len(binary[0]) < len(c):
            c,q = binary
            method = 'three-arm binary distribution + coherent decoders'
        subtraction = _subtract_balanced_seed(n,k)
        if subtraction is not None and len(subtraction[0]) < len(c):
            c,q = subtraction
            method = 'native balanced seed + deterministic measurement/complement'
        if n == 2*k and 6 <= n <= 14:
            adaptive = balanced_candidate(n)
            if len(adaptive['circuit']) < len(c):
                c, q = cirq.Circuit(adaptive['circuit']), set(adaptive['outputs'])
                method = 'adaptive cat complement + even-site teleportation'
    for op in c.all_operations():
        cirq_google.Willow105.validate_operation(op.without_classical_controls())
    if not c.has_measurements():
        cirq_google.Willow105.validate_circuit(c)
    return cirq.FrozenCircuit(c), frozenset(q), method


def create_dicke_state_adaptive(num_qubits, num_excitations):
    """Return a D(N,n) circuit in the notebook's scored domain.

    The interface permits feedforward; the portfolio may choose a shallower
    unitary circuit. N=2..20, n=1..floor(N/2). See evaluate.py for measured times.
    """
    if (type(num_qubits) is int and type(num_excitations) is int
            and 1 <= num_qubits <= len(cirq_google.Willow105.metadata.qubit_set)
            and num_excitations in (0, num_qubits)):
        qubits = set(sorted(cirq_google.Willow105.metadata.qubit_set)[:num_qubits])
        circuit = cirq.Circuit()
        if num_excitations:
            gate = cirq.PhasedXZGate(x_exponent=1, z_exponent=0, axis_phase_exponent=0)
            circuit.append(cirq.Moment(gate.on(q) for q in sorted(qubits)))
        return circuit, qubits
    if (isinstance(num_qubits, bool) or isinstance(num_excitations, bool)
            or not isinstance(num_qubits, int) or not isinstance(num_excitations, int)
            or not 2 <= num_qubits <= 20 or not 1 <= num_excitations <= num_qubits//2):
        raise NotImplementedError('Bonus domain: integer 2<=N<=20, 1<=n<=N//2')
    circuit, qubits, _ = _best(num_qubits, num_excitations)
    return cirq.Circuit(circuit), set(qubits)


def method_for(num_qubits, num_excitations):
    return _best(num_qubits, num_excitations)[2]


# Diagonal-safe adaptive complement; self-contained submission support.
def _layout(core_outputs, reserved=None):
    graph = _graph()
    core = set(core_outputs)
    reserved = core if reserved is None else set(reserved) | core
    odd = {q for q in graph if (q.row+q.col)%2}
    even = set(graph)-odd
    external_cats = odd-reserved
    assignment = {}
    # A core wire restored to zero can be a later teleportation destination.
    # It is still excluded from the concurrently prepared cat resource below.
    occupied = set(core)
    # Retained even sites need an outside neighboring cat.
    destinations = {q:q for q in core if q in even}
    for q in sorted(core & odd):
        candidates = [v for v in graph[q]-occupied if v in even
                      and graph[v] & external_cats]
        if not candidates:
            raise ValueError('No fresh even teleportation destination')
        v = min(candidates, key=lambda v: (-len(graph[v]&external_cats), v))
        destinations[q] = v
        occupied.add(v)
    usage = collections.Counter()
    for q, dest in sorted(destinations.items()):
        choices = graph[dest] & external_cats
        if not choices:
            raise ValueError('No outside cat neighbor for an even output')
        cat = min(choices, key=lambda c:(usage[c], c))
        usage[cat] += 1
        assignment[dest] = cat

    # Distance-two cat graph. Every chosen even mediator is outside the core;
    # a mediator may also be a future output, since it is restored to |0>.
    cat_graph = {q:{} for q in external_cats}
    for mediator in sorted(even-reserved):
        neighbors = sorted(graph[mediator] & external_cats)
        for a in neighbors:
            for b in neighbors:
                if a != b:
                    cat_graph[a].setdefault(b, mediator)
    terminals = set(assignment.values())
    best = None
    for root in sorted(cat_graph):
        parent = {root:None}
        distance = {root:0}
        queue = collections.deque([root])
        while queue:
            a = queue.popleft()
            for b in sorted(cat_graph[a]):
                if b not in parent:
                    parent[b] = a
                    distance[b] = distance[a]+1
                    queue.append(b)
        if not terminals <= parent.keys():
            continue
        included = {root}
        for terminal in terminals:
            v = terminal
            while v not in included:
                included.add(v)
                v = parent[v]
        edges = [(parent[q], q, cat_graph[parent[q]][q])
                 for q in sorted(included-{root}, key=lambda q:(distance[q],q))]
        ops = [(root,H)]
        for a,b,m in edges:
            _cx(ops,a,m)
            _cx(ops,m,b)
            _cx(ops,a,m)
        cat_circuit = _compile(ops)
        root_options = [(cat, target) for cat in included
                        for target in sorted(graph[cat]-occupied) if target in even]
        if not root_options:
            continue
        root_cat, output_root = min(root_options, key=lambda ct:(usage[ct[0]],ct))
        candidate = (len(cat_circuit), len(included), cat_circuit, included,
                     root_cat, output_root, edges)
        if best is None or candidate[:2] < best[:2]:
            best = candidate
    if best is None:
        raise ValueError('External cat graph is disconnected')
    _,_,cat_circuit,cats,root_cat,output_root,edges = best
    return dict(destinations=destinations, assignment=assignment,
                cat_circuit=cat_circuit, cats=cats, root_cat=root_cat,
                root=output_root, cat_edges=edges)


def _key(q):
    return f'odd_{q.row}_{q.col}'


def _parity(keys):
    return cirq.SympyCondition(sympy.Eq(sympy.Mod(sum(sympy.Symbol(k) for k in keys),2),1))


@functools.lru_cache(maxsize=8)
def balanced_candidate(n):
    if n%2 or not 6 <= n <= 14:
        raise ValueError('Use even N=6..14')
    k = n//2
    cores = []
    round4_core = _round4_unitary(n-1,k-1)
    if round4_core is not None:
        try:
            _layout(round4_core[1],reserved=round4_core[0].all_qubits())
            cores.append(round4_core)
        except ValueError:
            pass
    if not cores:
        for a in sorted({(n-1)//2,n//2}):
            for mode in [True,'pruned','fused']:
                candidate,output = _divide(n-1,k-1,a=a,small=mode)
                cores.append((_optimize_depth(candidate),output))
    seed = _native_seed(n-1,k-1)
    if seed is not None:
        cores.append(seed)
    binary = _binary_three_arm(n-1,k-1,open_center=True) if n == 10 else None
    if binary is not None:
        cores.append(binary)
    viable = []
    for candidate,output in sorted(cores,key=lambda pair:len(pair[0])):
        try:
            placement = _layout(output,reserved=candidate.all_qubits())
        except ValueError:
            continue
        viable.append((candidate,output,placement))
        break
    assert viable, 'No diagonal-safe cat/core layout'
    core,core_outputs,layout = viable[0]
    cat = layout['cat_circuit']
    # Nontrivial core and cat operations have disjoint supports. Preparing
    # the resource does not add serial depth until it exceeds core duration.
    assert not (core.all_qubits() & cat.all_qubits())
    prefix = cirq.Circuit(core.all_operations(), cat.all_operations())
    suffix_ops = []
    for old,dest in sorted(layout['destinations'].items()):
        if old != dest:
            _cx(suffix_ops,old,dest)
    for dest,control in sorted(layout['assignment'].items()):
        _cx(suffix_ops,control,dest)
    _cx(suffix_ops,layout['root_cat'],layout['root'])
    # Move the final X before measurement/correction. Its anticommutation
    # with the conditional Z contributes only a branch-global phase.
    _u(suffix_ops,layout['root'],X)
    odd = sorted(q for q in _graph() if (q.row+q.col)%2)
    measured_active = layout['cats'] | {q for q in core_outputs if (q.row+q.col)%2}
    for q in sorted(measured_active):
        _u(suffix_ops,q,H)
    suffix_unitary = _compile(suffix_ops)
    # Fuse every boundary and pack gates without ever moving across readout.
    prep_ops = []
    for op in itertools_ops(prefix, suffix_unitary):
        if len(op.qubits) == 1:
            prep_ops.append((op.qubits[0],cirq.unitary(op)))
        else:
            assert op.gate == cirq.CZ
            prep_ops.append(op.qubits)
    unscheduled_prefix = _compile(prep_ops)
    circuit = cirq.Circuit(_schedule_commuting(unscheduled_prefix, trials=16))
    circuit.append(cirq.Moment(cirq.measure(q,key=_key(q)) for q in odd))
    corrections = []
    correction_keys = {}
    for old,dest in sorted(layout['destinations'].items()):
        if old != dest:
            keys = [_key(old)]
            corrections.append(cirq.Z(dest).with_classical_controls(_key(old)))
            correction_keys[dest] = keys
    keys = sorted(_key(q) for q in measured_active)
    corrections.append(cirq.Z(layout['root']).with_classical_controls(_parity(keys)))
    correction_keys[layout['root']] = keys
    circuit.append(cirq.Moment(corrections))
    unscheduled_circuit = cirq.FrozenCircuit(circuit)
    # Full readout diagonals and feedforward are indivisible causal blocks;
    # independent final data gates may share their moments.
    circuit = _schedule_adaptive(circuit)
    outputs = set(layout['destinations'].values()) | {layout['root']}
    assert len(outputs) == n and all((q.row+q.col)%2 == 0 for q in outputs)
    return dict(circuit=cirq.FrozenCircuit(circuit), outputs=frozenset(outputs),
                core=cirq.FrozenCircuit(core), core_outputs=frozenset(core_outputs),
                cat=cirq.FrozenCircuit(cat), suffix=cirq.FrozenCircuit(suffix_unitary),
                unscheduled_prefix=cirq.FrozenCircuit(unscheduled_prefix),
                unscheduled_circuit=unscheduled_circuit,
                correction_keys=correction_keys, **layout)


def itertools_ops(*circuits):
    for circuit in circuits:
        yield from circuit.all_operations()




