def _round5_unitary(n, k):
    data = _ROUND5_VERIFIED.get((n, k))
    if data is None:
        return None
    q = [cirq.GridQubit(*v) for v in data['qubits']]
    moments = []
    for layer in data['moments']:
        ops = []
        for gate in layer:
            if len(gate) == 2:
                ops.append(cirq.CZ(q[gate[0]], q[gate[1]]))
            else:
                i, x, z, a = gate
                ops.append(cirq.PhasedXZGate(x_exponent=x, z_exponent=z,
                                           axis_phase_exponent=a).on(q[i]))
        moments.append(cirq.Moment(ops))
    return cirq.Circuit(moments), {q[i] for i in data['outputs']}
# ROUND 5 VERIFIED NATIVE CIRCUITS END


